patchSource("src/lib/supabase/rest.ts", (source) => {
  if (source.includes("export async function storageUpload")) throw new Error("Storage upload helpers already exist");
  return source.trimEnd() + "\n\n" + "\nfunction storageObjectPath(path: string): string {\n  return path.split(\"/\").map((part) => encodeURIComponent(part)).join(\"/\");\n}\n\nexport async function storageUpload(path: string, file: Blob, contentType: string): Promise<void> {\n  const response = await fetch(supabaseUrl() + \"/storage/v1/object/attendance-selfies/\" + storageObjectPath(path), {\n    method: \"POST\",\n    headers: { ...headers(), \"Content-Type\": contentType, \"x-upsert\": \"true\" },\n    body: file,\n    cache: \"no-store\",\n  });\n  await parseResponse<unknown>(response);\n}\n\nexport async function storageDelete(path: string): Promise<void> {\n  const response = await fetch(supabaseUrl() + \"/storage/v1/object/attendance-selfies\", {\n    method: \"DELETE\",\n    headers: { ...headers(), \"Content-Type\": \"application/json\" },\n    body: JSON.stringify({ prefixes: [path] }),\n    cache: \"no-store\",\n  });\n  await parseResponse<unknown>(response);\n}\n\nexport async function storageCreateSignedUrl(path: string, expiresIn = 300): Promise<string> {\n  const response = await fetch(supabaseUrl() + \"/storage/v1/object/sign/attendance-selfies/\" + storageObjectPath(path), {\n    method: \"POST\",\n    headers: { ...headers(), \"Content-Type\": \"application/json\" },\n    body: JSON.stringify({ expiresIn }),\n    cache: \"no-store\",\n  });\n  const result = await parseResponse<{ signedURL?: string; signedUrl?: string }>(response);\n  const signed = result.signedURL ?? result.signedUrl;\n  if (!signed) throw new Error(\"Supabase Storage returned no signed URL.\");\n  if (/^https?:\\/\\//i.test(signed)) return signed;\n  return supabaseUrl() + \"/storage/v1\" + (signed.startsWith(\"/\") ? signed : \"/\" + signed);\n}\n";
});

